<?php
require_once __DIR__.'/includes/bootstrap.php'; requireLogin();
$id=(int)($_GET['course_id']??$_POST['course_id']??0);$st=$pdo->prepare("SELECT * FROM courses WHERE id=? AND status='published'");$st->execute([$id]);$course=$st->fetch();if(!$course)die(t('course_not_found'));
$course=localizedCourse($course);
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $method=$_POST['payment_method']??'';$ref=trim($_POST['transaction_ref']??'');if(!in_array($method,['qicard','fib'],true))$error=t('payment_choose_error');elseif($method==='fib' && $ref==='')$error=t('payment_ref_error');elseif($method==='qicard' && (trim($_POST['cardholder_name']??'')==='' || preg_replace('/\D/','',$_POST['card_number']??'')==='' || trim($_POST['expiry_date']??'')==='' || trim($_POST['cvv']??'')===''))$error=t('qicard_fields_error');elseif($method==='qicard' && $ref==='')$ref='Qi Card checkout';else{$s=$pdo->prepare("INSERT INTO payments(user_id,course_id,amount_iqd,payment_method,status,transaction_ref) VALUES(?,?,?,?,?,?)");$s->execute([$_SESSION['user_id'],$id,$course['price_iqd'],$method,'pending',$ref]);$s=$pdo->prepare("INSERT INTO enrollments(user_id,course_id,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status='pending'");$s->execute([$_SESSION['user_id'],$id]);$success=t('payment_success');}}
$pageTitle=t('course_payment');require __DIR__.'/includes/header.php';?>
<section class="section"><div class="container" style="max-width:760px"><div class="card"><h1><?=t('pay_for')?> <?=e($course[localizedColumn('title')])?></h1><h2 class="price"><?=number_format((int)$course['price_iqd']).' '.t('iqd')?></h2><?php if($success):?><div class="card" style="border-left:4px solid #6d35cf"><?=e($success)?></div><?php else:?><p class="muted"><?=t('choose_payment_desc')?></p><div class="feature-grid"><div class="feature">💳 <?=t('qicard')?><br><small><?=t('qicard_desc')?></small></div><div class="feature">🏦 FIB<br><small><?=t('fib_desc')?></small></div></div><form method="post" style="margin-top:20px"><input type="hidden" name="course_id" value="<?=$id?>"><div class="field"><label><?=t('payment_method')?></label><select name="payment_method" id="payment_method" required onchange="showPaymentFields()"><option value="qicard"><?=t('qicard')?></option><option value="fib">FIB</option></select></div><div id="qicard-fields"><div class="field"><label><?=t('cardholder_name')?></label><input name="cardholder_name" autocomplete="cc-name"></div><div class="field"><label><?=t('card_number')?></label><input name="card_number" inputmode="numeric" autocomplete="cc-number" maxlength="19" placeholder="0000 0000 0000 0000"></div><div style="display:flex;gap:12px"><div class="field" style="flex:1"><label><?=t('expiry_date')?></label><input name="expiry_date" autocomplete="cc-exp" placeholder="MM/YY" maxlength="5"></div><div class="field" style="flex:1"><label><?=t('cvv')?></label><input name="cvv" type="password" inputmode="numeric" autocomplete="cc-csc" maxlength="4"></div></div><p class="muted" style="font-size:13px"><?=t('card_security_note')?></p></div><div id="fib-fields" style="display:none"><div class="field"><label><?=t('fib_payment_reference')?></label><input name="transaction_ref" placeholder="<?=e(t('transaction_reference'))?>"></div><p class="muted" style="font-size:13px"><?=t('fib_instruction')?></p></div><p class="muted" style="font-size:13px"><?=t('live_payment_note')?></p><?php if($error):?><p style="color:#a33"><?=e($error)?></p><?php endif;?><button class="btn" type="submit"><?=t('submit_payment')?></button></form><?php endif;?></div></div></section>
<script>function showPaymentFields(){const m=document.getElementById('payment_method').value;document.getElementById('qicard-fields').style.display=m==='qicard'?'block':'none';document.getElementById('fib-fields').style.display=m==='fib'?'block':'none';}</script><?php require __DIR__.'/includes/footer.php'; ?>